import { useState } from 'react'
import { Field } from 'moru-ui'
import { FileInput } from 'moru-ui'

export function DocumentPicker() {
  const [files, setFiles] = useState<File[]>([])
  return (
    <div>
      <Field
        label="Attach documents"
        description="Up to 3 PDF files, 5 MB each. Selection only; files are not uploaded."
      >
        <FileInput
          name="documents"
          accept=".pdf"
          multiple
          maxFiles={3}
          maxSize={5 * 1024 * 1024}
          onFilesChange={setFiles}
        />
      </Field>
      <p role="status">{files.length} files selected</p>
    </div>
  )
}
